  const sync = () => {
    const active = document.fullscreenElement === stage;
    button.setAttribute('aria-pressed', active ? 'true' : 'false');
    button.textContent = active ? 'Vollbild beenden' : 'Vollbild';
    stage.classList.toggle('is-fullscreen', active);
    instance?.refresh?.();
