  const sy = h / view.h;
  const ax = view.x + view.w * anchor.x;
  const ay = view.y + view.h * anchor.y;
  return clampView(
    {
      x: ax - (ax - view.x) * sx,
      y: ay - (ay - view.y) * sy,
      w,
      h,
    },
    bounds,
